1274		setActiveToolsByName(toolNames: string[]): void {
1275			// Fix #3 full variant (cache-break-investigation-2026-05-16.md §7.3 c):
1276			// builtin and alwaysLoad-tagged tools that were active before this call
1277			// stay active. Bridge log shows Bash/Edit/Write/Grep/Read each removed
1278			// ~2,560× per 18d — most plausibly extensions calling setActiveTools()
1279			// with a narrow list that doesn't re-include builtins (e.g. pi-tool-search
1280			// computing a curated active set, deferred-tool activation paths).
1281			//
1282			// Protection is additive and gated:
1283			//   - Only restores tools that were ALREADY active. Sessions created
1284			//     with `noTools: "builtin"` (builtins registered but inactive) stay
1285			//     inactive — we never add a tool that wasn't already active.
1286			//   - Only restores builtins (`allToolNames` set) and `alwaysLoad:true`
1287			//     tools. Extension tools and deferred tools follow the caller's
1288			//     replacement list as before.
1289			const orderedNames: string[] = [...toolNames];
1290			const previousActive = new Set(this.getActiveToolNames());
1291			for (const name of previousActive) {
